class Solution {
    public int minOperations(int n) {
        return Integer.bitCount(n ^ (3 * n));
    }
}

var minOperations = function(n) {
    let x = n ^ (3 * n);
    let count = 0;
    while (x > 0) {
        count += (x & 1);
        x >>= 1;
    }
    return count;
};
